/* Global Minified Script */
var App = {
    init: function() {
        this.initToastr();
        this.initSweetAlert();
        this.initDataTable();
    },
    initToastr: function() {
        if (typeof toastr !== 'undefined') {
            toastr.options = {
                closeButton: true,
                debug: false,
                newestOnTop: true,
                progressBar: true,
                positionClass: "toast-bottom-right",
                preventDuplicates: true,
                onclick: null,
                showDuration: "300",
                hideDuration: "1000",
                timeOut: "5000",
                extendedTimeOut: "1000",
                showEasing: "swing",
                hideEasing: "linear",
                showMethod: "fadeIn",
                hideMethod: "fadeOut"
            };
        }
    },
    initSweetAlert: function() {
        if (typeof Swal !== 'undefined') {
            window.swalConfirm = function(title, text) {
                return Swal.fire({
                    title: title || 'Tem certeza?',
                    text: text || 'Esta ação não pode ser desfeita!',
                    icon: 'warning',
                    showCancelButton: true,
                    confirmButtonColor: '#3085d6',
                    cancelButtonColor: '#d33',
                    confirmButtonText: 'Sim, confirmar!',
                    cancelButtonText: 'Cancelar'
                });
            };
        }
    },
    initDataTable: function() {
        if (typeof $.fn.DataTable !== 'undefined') {
            $.extend(true, $.fn.dataTable.defaults, {
                language: {
                    url: '//cdn.datatables.net/plug-ins/2.0.7/i18n/pt-BR.json'
                },
                responsive: true,
                pageLength: 10
            });
        }
    }
};

$(document).ready(function() {
    App.init();
});
